// Educational reconstruction. Coordinates are scaled from the official front/back
// component photographs; dimensions and logical buses are not manufacturing CAD.
const parts=[],nets=[];
function add(id,name,model,group,x,z,w,d,h,description,tags=[],kind='chip',side='bottom'){
  parts.push({id,name,model,group,x,z,w,d,h,description,tags:[side==='bottom'?'Back of board':'Front of board',...tags],kind,side});
}
function net(id,name,type,ids,info){nets.push({id,name,type,ids,info});}
add('mcu','Application processor','TI · AM6254','PROCESSING & MEMORY',-2,-7,7,7,.9,'Runs Linux and coordinates memory, storage, display, and peripheral interfaces. The chip contains four Cortex-A53 cores plus real-time processing subsystems.',['Quad-core A53','Up to 1.4 GHz']);
add('ddr','System memory','2 GB · DDR4','PROCESSING & MEMORY',-2,-15,7,5.5,.7,'Working memory for the operating system and applications. Its dedicated parallel DDR bus carries address, command, clock, and data signals.',['Volatile memory']);
add('emmc','Onboard storage','16 GB · eMMC','PROCESSING & MEMORY',7,-14,6.5,6,.7,'Soldered flash storage for the bootloader, Linux, and user files. Connected to the processor through its eight-bit MMC0 interface.',['MMC0','Nonvolatile']);
add('sd','microSD socket','Removable storage','PROCESSING & MEMORY',2,15,7,7,1.1,'Accepts a microSD card for booting, expanding storage, or installing an image to eMMC. Uses MMC1; it is a separate interface from onboard eMMC.',['MMC1'],'sd','top');
add('wifi','Wi-Fi module','TI · WL1807MOD','NETWORKING',15,11,6.5,6.5,1.1,'Dual-band Wi-Fi module connected through SDIO. Two external antenna sockets serve its radio paths. Bluetooth and sub-GHz functions are handled by the separate CC1352P7.',['2.4 / 5 GHz','SDIO'],'shield');
add('radio','Wireless microcontroller','TI · CC1352P7','NETWORKING',5,14,10,8,1.2,'A separate wireless MCU for BLE and sub-GHz networking. Linux communicates with its firmware over UART6. Radio capabilities depend on the loaded firmware.',['BLE','Sub-GHz'],'shield');
add('ethphy','Gigabit Ethernet PHY','Realtek · RTL8211F','NETWORKING',10,-2,3,3,.7,'Converts the processor’s RGMII interface into Ethernet signaling. The RJ45 connector includes magnetics between the PHY and the network cable.',['10 / 100 / 1000 Mb/s']);
add('spephy','Single-pair Ethernet PHY','TI · DP83TD510E','NETWORKING',5,5,3,3,.7,'Translates RMII data from the processor into 10BASE-T1L signaling over one twisted pair. The RJ11 port also provides a controlled power output.',['10 Mb/s','10BASE-T1L']);
add('rj45','Gigabit Ethernet port','RJ45 · integrated magnetics','CONNECTORS',-16,6,10,8,6,'Wired network connector. Signals pass through integrated magnetics to the RTL8211F PHY before reaching the processor.',['RJ45'],'rj45','top');
add('rj11','Single-pair Ethernet port','RJ11 · 10BASE-T1L','CONNECTORS',-16,14,10,7,5.5,'Single-pair Ethernet connection with power over the data line. The board documentation specifies a 5 V, 250 mA output; this port is not the board’s power input.',['PoDL output'],'rj11','top');
add('usbc','USB-C power & device','USB 2.0 · device role','CONNECTORS',-19,-16,4.5,4.5,1.8,'Supplies 5 V power and provides a USB device connection to a host computer. This connector does not negotiate higher USB-PD voltages.',['5 V input','USB0'],'usb','top');
add('usba','USB-A host','USB 2.0 · host role','CONNECTORS',-18,-8.5,7,4,3,'Connects peripherals such as keyboards, mice, and cameras to the USB1 host controller. A power switch feeds the port’s VBUS.',['480 Mb/s'],'usb','top');
add('hdmi','HDMI output','Type-A · full size','CONNECTORS',-16,-2,10,4.5,3,'Receives digital video from the IT66121 transmitter. The transmitter bridges the processor’s parallel display signals to HDMI.',['1080p output'],'hdmi','top');
add('hdmibridge','HDMI transmitter','ITE · IT66121','DISPLAY & CAMERA',-13,1,4.8,4.8,.65,'Bridges the parallel RGB display bus to HDMI. I²C2 configures the chip, and McASP1 supplies digital audio.',['RGB → HDMI']);
add('oldi','Display ribbon connector','OLDI · 40-pin FPC','DISPLAY & CAMERA',18,-13,2.8,13,1,'Connects a compatible LVDS/OLDI display. Display lanes run directly to the processor; control and power circuits support the panel.',['OLDI / LVDS'],'fpc','top');
add('csi','Camera ribbon connector','CSI-2 · 22-pin FPC','DISPLAY & CAMERA',18,-2,2.8,8,1,'Connects a compatible MIPI CSI-2 camera. Image data uses differential lanes, while a separate I²C link configures the camera.',['MIPI CSI-2'],'fpc','top');
add('mikro','mikroBUS socket','Expansion · 2 × 8 contacts','EXPANSION',7,3.5,13,12,2.4,'Accepts compatible Click boards. Select an individual contact below to trace its function. Bus assignment depends on the operating-system pin configuration.',['SPI / I²C / UART'],'socket','top');
add('grove','Grove connector','4-pin expansion','EXPANSION',18,6,4,6,2.6,'Expansion port exposing I²C1 with power and ground. Alternate functions depend on pin multiplexing and software configuration.',['I²C1'],'connector','top');
add('qwiic','Qwiic connector','4-pin JST-SH','EXPANSION',18,13,2.5,3.6,1.4,'Small I²C expansion connector compatible with Qwiic and STEMMA QT devices. It uses MCU_I2C0 and supplies 3.3 V.',['MCU_I2C0'],'connector','top');
add('adc','Analog converter','TI · ADC102S051','EXPANSION',-4,4.5,2.5,2,.55,'External two-channel, 10-bit ADC. It converts expansion analog signals into serial data for the processor. This is distinct from the digital GPIO paths.',['10-bit','SPI']);
add('pmic','Power management','TI · TPS65219 family','POWER & TIME',-17.5,-13,3,3,.7,'Sequences the processor and memory supplies. Several independently regulated outputs are shown as a grouped power connection, not as one shared voltage rail.',['Multiple rails']);
add('buck','3.3 V regulator','TI · TLV62595','POWER & TIME',-17,-8,2,2,.6,'Efficient step-down supply for the main 3.3 V rail and expansion connectors. The PMIC controls its enable input.',['3.3 V']);
add('ldo','1.0 V regulator','TI · TLV75801','POWER & TIME',2,8,1.6,1.4,.45,'Generates the 1.0 V supply used by the single-pair Ethernet PHY from a 1.8 V input rail.',['1.0 V']);
add('rtc','Real-time clock','TI · BQ32002','POWER & TIME',-13,-6,2.5,2.5,.55,'Keeps time independently of Linux. A backup coin cell can maintain the clock while main board power is off.',['I²C0 · 0x68']);
add('battery','RTC battery holder','CR1220 · 3 V','POWER & TIME',-8,-14,7.5,7.5,2,'Holds a CR1220 backup cell for the real-time clock. It does not power the main processor or charge a battery.',['Backup only'],'battery','top');
add('eeprom','Board identification','24C32 · EEPROM','POWER & TIME',-13,6.5,1.6,1.6,.5,'Stores board identification data on the local I²C0 bus. This small EEPROM is separate from the eMMC storage.',['I²C0 · 0x50']);
add('powerswitch','Peripheral power switches','USB / SPE support','POWER & TIME',-9,14,4,3.5,.7,'Grouped switching and protection circuitry for USB-A VBUS and single-pair Ethernet power output. The two output branches are separate.',['Grouped circuit']);
add('passives','Supply filtering & clocks','Capacitors · inductors · crystals','SUPPORT CIRCUITS',0,1,6,2,.45,'Grouped supporting components for supply bypassing and timing. The explorer omits individual oscillator, feedback, and decoupling nodes.',['Grouped circuit'],'passives');
add('powerbutton','Power button','Board power control','CONTROL & DEBUG',-9,19,2.5,1.6,.8,'Connects to the power-management control path for board power operations. Behavior depends on press duration and the running software.',['PMIC control'],'button','top');
add('reset','Reset button','System reset','CONTROL & DEBUG',-3.5,19,2.5,1.6,.8,'Requests a system reset. This is a separate control from powering off the board.',['Reset'],'button','top');
add('user','User / boot button','Boot selection & user input','CONTROL & DEBUG',13,19,2.5,1.6,.8,'Used for boot selection at startup and as a software input. The documentation describes holding it for SD-card boot selection.',['GPIO'],'button','top');
add('userled','User LEDs','Five indicators','CONTROL & DEBUG',-4,-19,3.8,1,.4,'Five processor-controlled LEDs provide software status and user feedback. Their GPIO lines are grouped in this view.',['GPIO group'],'ledbank','top');
add('statusled','Power & link LEDs','Status indicators','CONTROL & DEBUG',-15,19,3.8,1,.4,'Grouped power and connectivity indicators near the single-pair Ethernet connector. Different indicators are driven by different control circuits.',['Status group'],'ledbank','top');
add('debug','Processor JTAG','AM6254 · Tag-Connect','CONTROL & DEBUG',-1.5,-17,2.5,4,.1,'Test-pad interface for debugging the application processor. The JTAG signals are grouped as a bus here.',['JTAG'],'pads','top');
add('radiodebug','Radio JTAG','CC1352P7 · Tag-Connect','CONTROL & DEBUG',-4,15,2.5,4,.1,'Debug connection for the wireless MCU, separate from the AM6254 JTAG interface.',['JTAG'],'pads','top');
add('uart','Serial console','GND / RX / TX','CONTROL & DEBUG',-17,-12,4,1.5,1.2,'UART0 console for boot messages and a Linux terminal using a compatible logic-level serial adapter. This is not an RS-232 voltage interface.',['UART0'],'header','top');
for(const [id,name,x,z,target] of [['wifi1','Wi-Fi antenna 1',12,17,'wifi'],['wifi2','Wi-Fi antenna 2',17.5,17,'wifi'],['rf24','2.4 GHz antenna',-2,18,'radio'],['rfsub','Sub-GHz antenna',-2,15,'radio']]){add(id,name,'u.FL · external antenna','ANTENNAS',x,z,1.5,1.5,.55,'Coaxial antenna connection to the corresponding radio. The highlighted path includes the RF matching network as a functional group.',['RF connector'],'coax');net(id+'-rf',name+' · RF path','audio',[target,id],'RF feed through matching circuitry; this is not a GPIO signal.');}
const rows=[['AN','RST','CS','SCK','MISO','MOSI','3V3','GND'],['PWM','INT','RX','TX','SCL','SDA','5V','GND']];
rows.forEach((names,row)=>names.forEach((name,i)=>{add('mk-'+row+'-'+i,'mikroBUS '+name,'Socket contact · '+name,'MIKROBUS CONTACTS',row?12.7:1.3,-1.1+i*1.27,.8,.8,2.5,'Individual mikroBUS contact. The highlighted path shows its functional board connection; verify voltage and software pin configuration before connecting an add-on.',['Expansion contact'],'contact','top');}));
const contact=name=>parts.filter(p=>p.id.startsWith('mk-')&&p.name==='mikroBUS '+name).map(p=>p.id);
net('ddr','DDR4 · memory bus','signal',['mcu','ddr'],'Dedicated address, command, data and clock bundle.');
net('emmc','MMC0 · eMMC','signal',['mcu','emmc'],'Eight data lines plus command and clock.');
net('sd','MMC1 · microSD','signal',['mcu','sd'],'SD data, command, clock and card-detect functions.');
net('sdio','MMC2 / SDIO · Wi-Fi','signal',['mcu','wifi'],'Host interface to WL1807MOD; control signals are grouped.');
net('radio','UART6 · wireless MCU','signal',['mcu','radio'],'Serial communication to CC1352P7; reset and boot control are additional GPIO signals.');
net('rgmii','RGMII · Gigabit MAC ↔ PHY','signal',['mcu','ethphy'],'Processor Ethernet MAC to RTL8211F.');
net('rmii','RMII · single-pair MAC ↔ PHY','signal',['mcu','spephy'],'Processor Ethernet MAC to DP83TD510E.');
net('mdio','MDIO / MDC · PHY management','signal',['mcu','ethphy','spephy'],'Shared management interface for the Ethernet PHYs.');
net('ethernet','Ethernet · four twisted pairs','audio',['ethphy','rj45'],'PHY ↔ RJ45 through integrated magnetics.');
net('spe','10BASE-T1L · single pair','audio',['spephy','rj11'],'PHY ↔ RJ11 through coupling and termination circuitry.');
net('usb0','USB0 · device D+ / D−','audio',['mcu','usbc'],'USB device data pair, separate from connector power.');
net('usb1','USB1 · host D+ / D−','audio',['mcu','usba'],'USB host data pair for attached peripherals.');
net('rgb','DSS · 24-bit RGB display','signal',['mcu','hdmibridge'],'Parallel pixel, sync and clock bundle.');
net('audio','McASP1 · digital audio','audio',['mcu','hdmibridge'],'Serial audio supplied to the HDMI transmitter.');
net('hdmi','HDMI · TMDS / DDC / HPD','audio',['hdmibridge','hdmi'],'HDMI differential lanes and display control signals, grouped.');
net('i2c2','I²C2 · HDMI control','signal',['mcu','hdmibridge'],'Configuration interface to the IT66121 transmitter.');
net('oldi','OLDI · display lanes','audio',['mcu','oldi'],'LVDS pixel and clock lanes; panel power/control is grouped separately.');
net('csi','CSI-2 · camera lanes','audio',['mcu','csi'],'Differential image-data and clock lanes.');
net('camera-control','WKUP_I2C0 · camera control','signal',['mcu','csi'],'Camera configuration bus, separate from CSI image data.');
net('grove','I²C1 · Grove','signal',['mcu','grove'],'Expansion clock and data; alternate pin functions require software configuration.');
net('qwiic','MCU_I2C0 · Qwiic','signal',['mcu','qwiic'],'3.3 V I²C clock and data interface.');
net('mk-i2c','I²C3 · mikroBUS','signal',['mcu','mikro',...contact('SCL'),...contact('SDA')],'Separate clock and data conductors shown as one bus.');
net('mk-spi','SPI2 · mikroBUS','signal',['mcu','mikro',...contact('CS'),...contact('SCK'),...contact('MISO'),...contact('MOSI')],'Clock, chip select, input and output data bundle.');
net('mk-uart','UART5 · mikroBUS','signal',['mcu','mikro',...contact('RX'),...contact('TX')],'Separate receive and transmit paths.');
for(const name of ['PWM','RST','INT'])net('mk-'+name,name+' · mikroBUS control','signal',['mcu','mikro',...contact(name)],'Expansion control signal; actual mux and direction depend on software.');
net('adc-spi','SPI · ADC conversion data','signal',['mcu','adc'],'Serial interface for the external analog converter.');
net('analog','Analog · expansion inputs','signal',['adc','grove','mikro',...contact('AN')],'Two ADC channels are grouped; the analog inputs are not shorted together.');
net('local-i2c','I²C0 · board management','signal',['mcu','rtc','eeprom','pmic'],'Shared bus to RTC, board EEPROM and power management.');
net('backup','RTC backup supply','power',['battery','rtc'],'Coin-cell backup supply only.');
net('input','5 V · main input','power',['usbc','pmic','buck','powerswitch','mikro',...contact('5V')],'Main 5 V distribution; peripheral outputs pass through their switches.');
net('pmic-rails','PMIC · regulated rail bundle','power',['pmic','mcu','ddr','emmc','hdmibridge','ldo'],'Several distinct rails, including core, memory and I/O supplies. This bundle is not a single common net.');
net('3v3','3.3 V · board distribution','power',['buck','pmic','wifi','radio','ethphy','spephy','rtc','eeprom','adc','mikro','grove','qwiic','sd',...contact('3V3')],'Main 3.3 V supply; switchable branches are simplified.');
net('enable','PMIC · 3.3 V enable','signal',['pmic','buck'],'PMIC enable output controls the 3.3 V regulator.');
net('1v0','1.0 V · SPE supply','power',['ldo','spephy'],'Dedicated low-voltage supply for the DP83TD510E.');
net('usbpower','Switched 5 V · USB host','power',['powerswitch','usba'],'Switched USB-A VBUS.');
net('spepower','Switched 5 V · SPE PoDL','power',['powerswitch','rj11'],'Separate power-over-data-line output branch.');
net('panelpower','Display / HDMI power support','power',['pmic','powerswitch','oldi','hdmi'],'Grouped connector supply circuits; see official schematics for individual rails.');
net('powerbutton','Power-button control','signal',['powerbutton','pmic'],'Power-management input.');
net('reset','System reset control','signal',['reset','pmic','mcu'],'Functional system reset path.');
net('user','User / boot input','signal',['user','mcu'],'User button input sampled for boot selection.');
net('leds','User LED GPIO bundle','signal',['mcu','userled'],'Five independent GPIO-driven indicators, grouped.');
net('status','Status indication bundle','signal',['pmic','spephy','radio','statusled'],'Separate power and link indication circuits, grouped.');
net('debug','AM6254 · JTAG','signal',['mcu','debug'],'Processor debug bus.');
net('radiodebug','CC1352P7 · JTAG','signal',['radio','radiodebug'],'Radio MCU debug bus.');
net('console','UART0 · serial console','signal',['mcu','uart'],'Logic-level serial RX and TX.');
net('bypass','Supply bypass support','power',['pmic','buck','passives'],'Capacitors and regulator support grouped by function; no individual internal nodes are implied.');
net('gnd','GND · board reference','ground',parts.filter(p=>!p.id.startsWith('mk-')&&!['battery'].includes(p.id)).map(p=>p.id).concat(contact('GND')),'Common reference through PCB ground planes. Connector shielding and signal-return detail is simplified.');
export {parts,nets};
